import{_ as e,o as t,c as r,a2 as s}from"./chunks/framework.DuPBmefI.js";const h=JSON.parse('{"title":"圣若瑟书院 · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-ce82e0f8","school_zh":"圣若瑟书院","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"圣若瑟书院 · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-SJC"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/school-ce82e0f8/s1/2022-23-interview.md","filePath":"reports/school-ce82e0f8/s1/2022-23-interview.md"}'),p={name:"reports/school-ce82e0f8/s1/2022-23-interview.md"};function n(a,o,c,l,g,i){return t(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="圣若瑟书院-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">圣若瑟书院 · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#圣若瑟书院-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;圣若瑟书院 · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-ce82e0f8">← 返回圣若瑟书院资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-sjc" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-sjc" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-sjc}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>先小组、后个人</strong></p><p>先进行六人英语小组讨论，再个人考核中英数，整个流程约30至45分钟。不同场次的题目有差异；有组别由副校长主持小组环节。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>六人小组讨论</strong></p><p>不同组别讨论：如何提升领导能力；怎样成为一位好的学校图书管理员；私人补习是否对学习重要；诚实、善良与聪明三种特质中哪一种最重要。</p><p><strong>文章朗读与问答</strong></p><p>朗读文章后回答相关问题，常见反馈为两道题。一组文章涉及新冠疫情，延伸问题包括是否喜欢网课、老师会用哪些有趣材料促进学习；另有学生比较网课与面对面课堂。</p><p><strong>阅读习惯</strong></p><p>回答是否喜欢阅读，并分享一本英文书。</p></blockquote><blockquote><p><strong>语文：</strong> 粤语、普通话</p><p><strong>成语与普通话</strong></p><p>一组完成四道成语选择题：按成语选意思、按意思选成语，或选择含义相近的成语；另一组为五道成语填充。普通话环节有三组词语读音，例如“一盘棋”“指导”，也有朗读文章的反馈。</p><p><strong>一分钟短讲</strong></p><p>不同题目包括介绍一位歌坛或演艺界人物、劝朋友不要沉迷电子游戏，以及一次难忘的外游经历。</p></blockquote><blockquote><p><strong>数学：</strong> 英语</p><p><strong>全英文题目与解释</strong></p><p>数学没有中文对照，须用英语对答并解释选择答案的原因。一组为两题；另有反馈为限时完成三至五题，考生实际答了三题，第一题直接报答案，后两题选A、B、C、D后解释。</p><p><strong>记得的题目</strong></p><p>题目包括解方程3/4 × (x − 2) = 6、计算25 × 23 × 4 − 300、体积、图形面积，以及选择答案后解释理由的逻辑推理题。</p></blockquote><blockquote><p><strong>学生反馈：</strong></p><p><strong>难度体验</strong></p><p>一位学生觉得整体题目不难，有较充分的表达机会。</p></blockquote>',13)])])}const _=e(p,[["render",n]]);export{h as __pageData,_ as default};
